//! Everything `espforge` does between an ESPF file and generated bytes, with
//! no opinion about how a terminal should look.
//!
//! Phase 4 moves the pipeline out of the binary: [`pipeline`] validates and
//! lowers, [`source`] finds the spec and the files beside it, [`spec`] writes
//! ESPF back out, [`board_json`] is the machine-readable board, and
//! [`answers`] applies command-line overrides, and [`project`] turns a
//! validated spec into the files on disk. Nothing here prints or exits;
//! `espforge` keeps the argument parsing, the rendering and the exit codes.

pub mod answers;
pub mod board_json;
pub mod frontend;
pub mod pipeline;
pub mod project;
pub mod source;
pub mod spec;
